INSERT INTO government_schemes (scheme_name, description, eligibility, benefits, application_info, official_url, verification_status, is_demo) SELECT 'Sample maternal support resource', 'Demo content placeholder for a government scheme card.', 'Verify current eligibility on the official government website.', 'Benefits and terms should be confirmed from the official source.', 'Use the official portal linked by your administrator.', NULL, 'unverified', TRUE WHERE NOT EXISTS (SELECT 1 FROM government_schemes WHERE scheme_name = 'Sample maternal support resource');
INSERT INTO health_content (title, category, summary, body, verification_status) SELECT 'A gentler approach to everyday nourishment', 'nutrition', 'General ideas for building balanced meals.', 'This is educational content only. Speak with a qualified healthcare professional for personalised dietary advice.', 'unverified' WHERE NOT EXISTS (SELECT 1 FROM health_content WHERE title = 'A gentler approach to everyday nourishment');
INSERT INTO health_content (title, category, summary, body, verification_status) SELECT 'Rest, movement and your changing routine', 'wellness', 'Small ways to notice what your body needs.', 'General wellness information is not a personalised exercise prescription.', 'unverified' WHERE NOT EXISTS (SELECT 1 FROM health_content WHERE title = 'Rest, movement and your changing routine');
INSERT INTO facilities (name, facility_type, address, phone, source_url, verification_status, is_demo) SELECT 'Demo Community Hospital', 'hospital', 'Demo address — verify before visiting', NULL, NULL, 'unverified', TRUE WHERE NOT EXISTS (SELECT 1 FROM facilities WHERE name = 'Demo Community Hospital');
